package com.backendSupermercado.supermercasdo.modules.reportes.personal.controller;
import java.time.LocalDate;import java.util.*;import org.springframework.data.domain.*;import org.springframework.http.*;import org.springframework.web.bind.annotation.*;import com.backendSupermercado.supermercasdo.modules.reportes.personal.model.TipoReportePersonal;import com.backendSupermercado.supermercasdo.modules.reportes.personal.repository.ReportePersonalRepository;import com.backendSupermercado.supermercasdo.modules.reportes.venta.dto.ReporteVentaExportacion;import com.backendSupermercado.supermercasdo.modules.reportes.venta.service.*;
@RestController@RequestMapping("/api/reportes/personal")public class ReportePersonalController{private final ReportePersonalRepository repo;private final ReporteVentaPdfService pdf;private final ReporteVentaExcelService excel;public ReportePersonalController(ReportePersonalRepository r,ReporteVentaPdfService p,ReporteVentaExcelService e){repo=r;pdf=p;excel=e;}@GetMapping("/{tipo}")public Page<Map<String,Object>> consultar(@PathVariable String tipo,@RequestParam Map<String,String>f,@RequestParam(defaultValue="0")int page,@RequestParam(defaultValue="10")int size){return repo.consultar(TipoReportePersonal.desdeRuta(tipo).ruta(),n(f),PageRequest.of(page,size));}@GetMapping(value="/{tipo}/pdf",produces=MediaType.APPLICATION_PDF_VALUE)public ResponseEntity<byte[]>pdf(@PathVariable String tipo,@RequestParam Map<String,String>f){TipoReportePersonal t=TipoReportePersonal.desdeRuta(tipo);return archivo(pdf.generar(exp(t,n(f))),"reporte-personal-"+t.ruta()+".pdf",MediaType.APPLICATION_PDF);}@GetMapping(value="/{tipo}/excel",produces="application/vnd.openxmlformats-officedocument.spreadsheetml.sheet")public ResponseEntity<byte[]>excel(@PathVariable String tipo,@RequestParam Map<String,String>f){TipoReportePersonal t=TipoReportePersonal.desdeRuta(tipo);return archivo(excel.generar(exp(t,n(f))),"reporte-personal-"+t.ruta()+".xlsx",MediaType.parseMediaType("application/vnd.openxmlformats-officedocument.spreadsheetml.sheet"));}private ReporteVentaExportacion exp(TipoReportePersonal t,Map<String,Object>f){List<Map<String,Object>>d=repo.consultar(t.ruta(),f,Pageable.unpaged()).getContent();List<String>c=List.of("Fecha","Empleado","Estado","Detalle");List<List<String>>rows=d.stream().map(x->List.of(v(x,"fecha"),v(x,"empleado"),v(x,"estado"),v(x,"cargo"))).toList();return new ReporteVentaExportacion(t.titulo(),"Filtros aplicados: "+f,c,rows);}private String v(Map<String,Object>m,String k){return m.get(k)==null?"-":String.valueOf(m.get(k));}private Map<String,Object>n(Map<String,String>i){Map<String,Object>o=new LinkedHashMap<>();i.forEach((k,v)->{if(v!=null&&!v.isBlank())o.put(k,v);});return o;}private ResponseEntity<byte[]>archivo(byte[]b,String n,MediaType m){return ResponseEntity.ok().contentType(m).contentLength(b.length).header(HttpHeaders.CONTENT_DISPOSITION,"attachment; filename=\""+n+"\"").header("X-Generated-Date",LocalDate.now().toString()).body(b);}}
